//! Probe: verify clap 4.6.7 external-subcommand semantics.
#![allow(unreachable_pub)]

use clap::Parser;
use clap::Subcommand;

#[derive(Parser, Debug, PartialEq)]
#[command(name = "tool")]
pub struct Cli {
    #[arg(long, global = true, default_value = "builtin.toml")]
    pub config: String,
    #[arg(long, global = true)]
    pub define: Vec<String>,
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug, PartialEq)]
pub enum Commands {
    #[command(alias = "r")]
    Run(RunArgs),
    #[command(external_subcommand)]
    External(Vec<String>),
}

#[derive(clap::Args, Debug, PartialEq)]
pub struct RunArgs {
    #[arg(long, required = true)]
    pub output: String,
    #[arg(last = true)]
    pub trailing: Vec<String>,
}

#[cfg(test)]
mod probe {
    use super::*;
    use clap::error::ErrorKind;

    fn show(argv: &[&str]) {
        match Cli::try_parse_from(argv) {
            Ok(cli) => eprintln!("OK   {argv:?} => {cli:?}"),
            Err(e) => eprintln!(
                "ERR  {argv:?} => {:?}: {}",
                e.kind(),
                e.to_string().replace('\n', " | ")
            ),
        }
    }

    #[test]
    fn probe_behaviors() {
        show(&["tool", "foo"]);
        show(&["tool", "foo", "--flag"]);
        show(&["tool", "foo", "run", "r"]);
        show(&["tool", "foo", "--", "x", "--config", "y"]);
        show(&["tool", "foo", ""]);
        show(&["tool", "--", "foo", "--flag"]);
        show(&["tool", "--", "--flag"]);
        show(&["tool", "--", ""]);
        show(&["tool", "run", "-r"]); // alias as short?
        show(&["tool", "r", "--output", "o"]);
        show(&["tool", "run", "--output", "o", "--", "--config", "run", "--"]);
        show(&["tool", "run", "--output"]);
        show(&["tool", "--define", "bad", "foo"]);
        show(&["tool", "--bogus", "foo"]);
        show(&["tool", "--config"]);
        show(&["tool", "--define"]);
        show(&["tool", "foo", "--config", "x"]); // does external steal global after name?
        show(&["tool", "--config", "c.toml", "--define", "a=1", "plug", "--define", "b=2"]);
        show(&["tool", "--help"]);
        show(&["tool", "run", "--help"]);
        show(&["tool", "run"]);
        show(&["tool", "foo", "--help"]);
        show(&["tool", "--help", "foo"]);
        show(&["tool"]);
    }
}

